Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='paysforgrowth', at=datetime(2026, 11, 5, 0, 0, 0), actor='assistant', title='Each pull request pays for its own growth of the reading set', body="A pull request's reading-set delta against master, from scripts/context.sh, is at most zero. It pays for what it adds by deleting narration comments, dead code and copies in the files it touches, never by cutting a capability. The ratchet's allowance is per tree, not per pull request, so two growing pull requests fail a train together. A pull request that cannot pay says so in its body and is reviewed on that.", rationale='2026-11-05, train 212: two pull requests that each added about 5k tokens failed a train together against a ratchet recorded tight.', supersedes=()))